        "path": "BrightMemoryTrainer/Program.cs",
        "content": "using BrightMemoryTrainer.Core;\n\nnamespace BrightMemoryTrainer;\n\n/// <summary>\n/// Entry point for the Bright Memory Trainer.\n/// This tool provides memory editing capabilities for the Bright Memory game.\n/// </summary>\ninternal static class Program\n{\n    private static async Task Main(string[] args)\n    {\n        Console.WriteLine(\"Bright Memory Trainer v1.0\");\n        Console.WriteLine(\"===========================\");\n\n        // Initialize the memory scanner\n        var scanner = new MemoryScanner(\"BrightMemory-Win64-Shipping\");\n\n        if (!scanner.AttachToProcess())\n        {\n            Console.WriteLine(\"Failed to attach to Bright Memory process. Ensure the game is running.\");\n            return;\n        }\n\n        Console.WriteLine(\"Attached to Bright Memory process.\");\n\n        // Example: find health value (float) and freeze it\n        var healthAddress = scanner.ScanForValue<float>(100.0f, out bool found);\n        if (found)\n        {\n            Console.WriteLine($\"Health found at address: 0x{healthAddress:X}\");\n            scanner.FreezeValue<float>(healthAddress, 100.0f);\n            Console.WriteLine(\"Health frozen to 100.\");\n        }\n        else\n        {\n            Console.WriteLine(\"Health value not found. Try adjusting the game first.\");\n        }\n\n        // Keep the trainer open until user presses a key\n        Console.WriteLine(\"\\nPress any key to exit...\");\n        Console.ReadKey();\n\n        scanner.UnfreezeAll();\n    }\n}"
    },
