        "path": "BrightMemoryTrainer/Core/MemoryScanner.cs",
        "content": "using System.Diagnostics;\nusing System.Runtime.InteropServices;\n\nnamespace BrightMemoryTrainer.Core;\n\n/// <summary>\n/// Provides memory scanning and manipulation functionality for a target process.\n/// Uses Windows kernel32.dll functions for memory operations.\n/// </summary>\npublic class MemoryScanner\n{\n    private readonly string _processName;\n    private IntPtr _processHandle;\n    private Process? _targetProcess;\n    private readonly List<FrozenValue> _frozenValues = new();\n\n    /// <summary>\n    /// Initializes a new instance of the MemoryScanner class.\n    /// </summary>\n    /// <param name=\"processName\">Name of the target process (without .exe).</param>\n    public MemoryScanner(string processName)\n    {\n        _processName = processName;\n        _processHandle = IntPtr.Zero;\n    }\n\n    /// <summary>\n    /// Attaches to the target process by name.\n    /// </summary>\n    /// <returns>True if attachment succeeded, false otherwise.</returns>\n    public bool AttachToProcess()\n    {\n        var processes = Process.GetProcessesByName(_processName);\n        if (processes.Length == 0)\n            return false;\n\n        _targetProcess = processes[0];\n        _processHandle = OpenProcess(ProcessAccessFlags.All, false, _targetProcess.Id);\n        return _processHandle != IntPtr.Zero;\n    }\n\n    /// <summary>\n    /// Scans the process memory for a specific value of type T.\n    /// </summary>\n    /// <typeparam name=\"T\">Unmanaged type to scan for (e.g., int, float).</typeparam>\n    /// <param name=\"value\">The value to find.</param>\n    /// <param name=\"found\">Outputs whether the value was found.</param>\n    /// <returns>Memory address of the first occurrence, or IntPtr.Zero if not found.</returns>\n    public IntPtr ScanForValue<T>(T value, out bool found) where T : unmanaged\n    {\n        found = false;\n        if (_targetProcess == null || _processHandle == IntPtr.Zero)\n            return IntPtr.Zero;\n\n        var size = Marshal.SizeOf<T>();\n        var buffer = new byte[size];\n        var address = IntPtr.Zero;\n\n        // Simple linear scan through the process memory regions\n        while (VirtualQueryEx(_processHandle, address, out MEMORY_BASIC_INFORMATION mbi, (uint)Marshal.SizeOf<MEMORY_BASIC_INFORMATION>()) != 0)\n        {\n            if (mbi.State == MemCommit && mbi.Protect == PageReadWrite)\n            {\n                var regionSize = (int)mbi.RegionSize;\n                var regionData = new byte[regionSize];\n                if (ReadProcessMemory(_processHandle, mbi.BaseAddress, regionData, regionSize, out _))\n                {\n                    for (int i = 0; i <= regionSize - size; i++)\n                    {\n                        var slice = regionData[i..(i + size)];\n                        var currentValue = MemoryMarshal.Read<T>(slice);\n                        if (currentValue.Equals(value))\n                        {\n                            found = true;\n                            return mbi.BaseAddress + i;\n                        }\n                    }\n                }\n            }\n            address = mbi.BaseAddress + (int)mbi.RegionSize;\n        }\n\n        return IntPtr.Zero;\n    }\n\n    /// <summary>\n    /// Freezes a value at a given memory address by continuously writing to it.\n    /// </summary>\n    /// <typeparam name=\"T\">Unmanaged type of the value.</typeparam>\n    /// <param name=\"address\">Memory address to freeze.</param>\n    /// <param name=\"value\">Value to write repeatedly.</param>\n    public void FreezeValue<T>(IntPtr address, T value) where T : unmanaged\n    {\n        if (_processHandle == IntPtr.Zero)\n            return;\n\n        var frozen = new FrozenValue\n        {\n            Address = address,\n            Type = typeof(T)\n        };\n\n        _frozenValues.Add(frozen);\n\n        // Start a background task to write the value periodically\n        _ = Task.Run(async () =>\n        {\n            while (frozen.IsActive)\n            {\n                var bytes = new byte[Marshal.SizeOf<T>()];\n                MemoryMarshal.Write(bytes, ref value);\n                WriteProcessMemory(_processHandle, address, bytes, bytes.Length, out _);\n                await Task.Delay(50); // 20 Hz refresh\n            }\n        });\n    }\n\n    /// <summary>\n    /// Unfreezes all previously frozen values.\n    /// </summary>\n    public void UnfreezeAll()\n    {\n        foreach (var fv in _frozenValues)\n        {\n            fv.IsActive = false;\n        }\n        _frozenValues.Clear();\n    }\n\n    // Windows API imports\n    [DllImport(\"kernel32.dll\", SetLastError = true)]\n    private static extern IntPtr OpenProcess(ProcessAccessFlags dwDesiredAccess, bool bInheritHandle, int dwProcessId);\n\n    [DllImport(\"kernel32.dll\", SetLastError = true)]\n    private static extern bool ReadProcessMemory(IntPtr hProcess, IntPtr lpBaseAddress, byte[] lpBuffer, int dwSize, out int lpNumberOfBytesRead);\n\n    [DllImport(\"kernel32.dll\", SetLastError = true)]\n    private static extern bool WriteProcessMemory(IntPtr hProcess, IntPtr lpBaseAddress, byte[] lpBuffer, int nSize, out int lpNumberOfBytesWritten);\n\n    [DllImport(\"kernel32.dll\", SetLastError = true)]\n    private static extern int VirtualQueryEx(IntPtr hProcess, IntPtr lpAddress, out MEMORY_BASIC_INFORMATION lpBuffer, uint dwLength);\n\n    [StructLayout(LayoutKind.Sequential)]\n    private struct MEMORY_BASIC_INFORMATION\n    {\n        public IntPtr BaseAddress;\n        public IntPtr AllocationBase;\n        public uint AllocationProtect;\n        public IntPtr RegionSize;\n        public uint State;\n        public uint Protect;\n        public uint Type;\n    }\n\n    private const uint MemCommit = 0x1000;\n    private const uint PageReadWrite = 0x04;\n\n    [Flags]\n    private enum ProcessAccessFlags : uint\n    {\n        All = 0x001F0FFF,\n        Terminate = 0x00000001,\n        CreateThread = 0x00000002,\n        VMOperation = 0x00000008,\n        VMRead = 0x00000010,\n        VMWrite = 0x00000020,\n        DupHandle = 0x00000040,\n        SetInformation = 0x00000200,\n        QueryInformation = 0x00000400,\n        Synchronize = 0x00100000\n    }\n\n    private class FrozenValue\n    {\n        public IntPtr Address { get; set; }\n        public Type Type { get; set; } = typeof(int);\n        public bool IsActive { get; set; } = true;\n    }\n}"
    },
