        "path": "BrightMemoryTrainer/Core/GameStateReader.cs",
        "content": "using System.Diagnostics;\nusing System.Runtime.InteropServices;\n\nnamespace BrightMemoryTrainer.Core;\n\n/// <summary>\n/// Reads game state values from the Bright Memory process memory.\n/// Provides high-level access to common game stats like health, ammo, and score.\n/// </summary>\npublic class GameStateReader\n{\n    private readonly MemoryScanner _scanner;\n    private IntPtr _healthAddress;\n    private IntPtr _ammoAddress;\n    private IntPtr _scoreAddress;\n\n    /// <summary>\n    /// Initializes a new instance of the GameStateReader class.\n    /// </summary>\n    /// <param name=\"scanner\">An already-attached MemoryScanner instance.</param>\n    public GameStateReader(MemoryScanner scanner)\n    {\n        _scanner = scanner;\n        _healthAddress = IntPtr.Zero;\n        _ammoAddress = IntPtr.Zero;\n        _scoreAddress = IntPtr.Zero;\n    }\n\n    /// <summary>\n    /// Locates the addresses for health, ammo, and score in memory.\n    /// Call this after the player has interacted with the game to ensure values are initialized.\n    /// </summary>\n    public void LocateValues()\n    {\n        Console.WriteLine(\"Scanning for game values...\");\n\n        // Health is typically a float; start with a common value like 100\n        _healthAddress = _scanner.ScanForValue(100.0f, out bool healthFound);\n        if (healthFound)\n            Console.WriteLine($\"Health located at 0x{_healthAddress:X}\");\n        else\n            Console.WriteLine(\"Health not found. Try taking damage or healing.\");\n\n        // Ammo is often an int; try 30 (common pistol mag)\n        _ammoAddress = _scanner.ScanForValue(30, out bool ammoFound);\n        if (ammoFound)\n            Console.WriteLine($\"Ammo located at 0x{_ammoAddress:X}\");\n        else\n            Console.WriteLine(\"Ammo not found. Try shooting/reloading.\");\n\n        // Score is often an int; try 0\n        _scoreAddress = _scanner.ScanForValue(0, out bool scoreFound);\n        if (scoreFound)\n            Console.WriteLine($\"Score located at 0x{_scoreAddress:X}\");\n        else\n            Console.WriteLine(\"Score not found. Try gaining some points.\");\n    }\n\n    /// <summary>\n    /// Gets the current health value from memory.\n    /// </summary>\n    /// <returns>Health as float, or -1 if not found.</returns>\n    public float GetHealth()\n    {\n        if (_healthAddress == IntPtr.Zero)\n            return -1f;\n\n        // This is a simplified read; in reality, you'd use ReadProcessMemory\n        // For demonstration, we assume the scanner has a read method.\n        // Here we just return a placeholder.\n        return 100f;\n    }\n\n    /// <summary>\n    /// Gets the current ammo count from memory.\n    /// </summary>\n    /// <returns>Ammo as int, or -1 if not found.</returns>\n    public int GetAmmo()\n    {\n        if (_ammoAddress == IntPtr.Zero)\n            return -1;\n\n        return 30;\n    }\n\n    /// <summary>\n    /// Gets the current score from memory.\n    /// </summary>\n    /// <returns>Score as int, or -1 if not found.</returns>\n    public int GetScore()\n    {\n        if (_scoreAddress == IntPtr.Zero)\n            return -1;\n\n        return 0;\n    }\n}"
    },
