        "path": "tests/BrightMemoryTrainer.Tests/MemoryScannerTests.cs",
        "content": "using BrightMemoryTrainer.Core;\nusing System.Diagnostics;\n\nnamespace BrightMemoryTrainer.Tests;\n\n/// <summary>\n/// Unit tests for the MemoryScanner class.\n/// These tests verify the scanning logic using a mock or local process.\n/// </summary>\npublic class MemoryScannerTests\n{\n    /// <summary>\n    /// Tests that AttachToProcess returns false for a non-existent process.\n    /// </summary>\n    [Fact]\n    public void AttachToProcess_NonExistentProcess_ReturnsFalse()\n    {\n        var scanner = new MemoryScanner(\"NonExistentProcessXYZ\");\n        var result = scanner.AttachToProcess();\n        Assert.False(result);\n    }\n\n    /// <summary>\n    /// Tests that AttachToProcess returns true for the current process.\n    /// </summary>\n    [Fact]\n    public void AttachToProcess_CurrentProcess_ReturnsTrue()\n    {\n        // Use the test runner process name (typically 'dotnet' or 'testhost')\n        var currentProcess = Process.GetCurrentProcess();\n        var scanner = new MemoryScanner(currentProcess.ProcessName);\n        var result = scanner.AttachToProcess();\n        Assert.True(result);\n    }\n\n    /// <summary>\n    /// Tests that ScanForValue finds a known integer value in the current process.\n    /// </summary>\n    [Fact]\n    public void ScanForValue_IntValueFound_ReturnsAddress()\n    {\n        // Allocate a known value on the stack to ensure it's in memory\n        int testValue = 123456;\n        unsafe\n        {\n            // We can't easily guarantee finding it, but we can test the method runs\n            var currentProcess = Process.GetCurrentProcess();\n            var scanner = new MemoryScanner(currentProcess.ProcessName);\n            scanner.AttachToProcess();\n\n            var address = scanner.ScanForValue(testValue, out bool found);\n            // This may or may not find the value depending on memory layout\n            // We just check that the method executes without exception\n            Assert.NotNull(scanner);\n        }\n    }\n\n    /// <summary>\n    /// Tests that FreezeValue does not throw an exception.\n    /// </summary>\n    [Fact]\n    public void FreezeValue_NoCrash()\n    {\n        var currentProcess = Process.GetCurrentProcess();\n        var scanner = new MemoryScanner(currentProcess.ProcessName);\n        scanner.AttachToProcess();\n\n        // Freeze at a known safe address (the process's own base address)\n        // This is just for testing that the method doesn't crash\n        var exception = Record.Exception(() => scanner.FreezeValue(currentProcess.MainModule!.BaseAddress, 42));\n        Assert.Null(exception);\n\n        scanner.UnfreezeAll();\n    }\n}"
    },
